<div class="page-heading"><div><span class="eyebrow">Parent · Child details</span><h1>My children</h1><p>Add, update, and maintain the details used for vaccination scheduling.</p></div><button class="button" type="button" data-dialog-open="child-form"><?= $editing ? 'Edit child' : 'Add child' ?></button></div>
<section class="card-grid child-grid"><?php foreach ($children as $child): ?><article class="info-card"><div class="card-top"><span class="initial-badge large"><?= e(mb_strtoupper(mb_substr($child['name'], 0, 1))) ?></span><span class="dose-count"><?= (int) $child['completed_doses'] ?> doses</span></div><h2><?= e($child['name']) ?></h2><p><?= e(age_label($child['date_of_birth'])) ?> · <?= e(status_label($child['gender'])) ?><?= $child['blood_group'] ? ' · ' . e($child['blood_group']) : '' ?></p><dl><div><dt>Date of birth</dt><dd><?= e(display_date($child['date_of_birth'])) ?></dd></div><div><dt>Medical notes</dt><dd><?= e($child['medical_notes'] ?: 'No medical notes') ?></dd></div></dl><div class="card-actions"><a class="button button-secondary button-small" href="<?= e(url('parent.children', ['edit' => $child['id']])) ?>">Edit</a><form method="post" action="<?= e(url('parent.child.delete')) ?>" data-confirm="Delete this child and all linked booking and vaccination records? This cannot be undone."><?= csrf_field() ?><input type="hidden" name="child_id" value="<?= (int) $child['id'] ?>"><button class="button button-quiet button-small" type="submit">Delete</button></form></div></article><?php endforeach; ?><?php if (!$children): ?><div class="empty-state compact"><span class="empty-icon">+</span><h2>No child details yet</h2><p>Add the first child to receive calculated vaccination dates.</p></div><?php endif; ?></section>
<dialog id="child-form" class="dialog" <?= $editing ? 'data-open-on-load' : '' ?>><form method="post" action="<?= e(url('parent.child.save')) ?>" data-validate><?= csrf_field() ?><input type="hidden" name="child_id" value="<?= (int) ($editing['id'] ?? 0) ?>"><div class="dialog-heading"><div><span class="eyebrow"><?= $editing ? 'Update profile' : 'New child' ?></span><h2><?= $editing ? 'Edit child details' : 'Add child details' ?></h2></div><button type="button" data-dialog-close aria-label="Close">×</button></div><div class="form-grid"><label>Child name<input name="name" value="<?= e($editing['name'] ?? '') ?>" minlength="2" maxlength="100" required></label><label>Date of birth<input type="date" name="date_of_birth" value="<?= e($editing['date_of_birth'] ?? '') ?>" max="<?= e(date('Y-m-d')) ?>" required></label><label>Gender<select name="gender" required><option value="">Choose</option><?php foreach (['female','male','other'] as $gender): ?><option value="<?= e($gender) ?>" <?= ($editing['gender'] ?? '') === $gender ? 'selected' : '' ?>><?= e(status_label($gender)) ?></option><?php endforeach; ?></select></label><label>Blood group<select name="blood_group"><option value="">Not specified</option><?php foreach (['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $group): ?><option value="<?= e($group) ?>" <?= ($editing['blood_group'] ?? '') === $group ? 'selected' : '' ?>><?= e($group) ?></option><?php endforeach; ?></select></label><label class="span-2">Medical notes <small>Allergies or information the hospital should know</small><textarea name="medical_notes" rows="3" maxlength="500"><?= e($editing['medical_notes'] ?? '') ?></textarea></label></div><button class="button button-full" type="submit"><?= $editing ? 'Save child details' : 'Add child' ?></button></form></dialog>
